	return fmt.Sprintf("error: The argument '%s' requires a value but none was supplied\n\nUSAGE:\n    executable %s\n\nFor more information try --help\n", missingLong, strings.Join(all, " "))
}

func usageForDuplicate(dupLong string, present []string) string {
	all := append([]string{}, present...)
	found := false
	for _, p := range all {
		if p == dupLong {
			found = true
			break
		}
	}
	if !found {
		all = append(all, dupLong)
	}
	sort.Strings(all)
	return fmt.Sprintf("error: The argument '%s' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    executable %s\n\nFor more information try --help\n", dupLong, strings.Join(all, " "))
}

