									j = len(arg)
								}
							}
						}
					}
					// break out of char loop (since remainder consumed)
					break
				default:
					// unknown short
					if !hasErr {
						msg := fmt.Sprintf("error: Found argument '-%c' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [--] [selector]...\n\nFor more information try --help\n", c)
