					j = len(arg)
					break
				}
			}
			if consumedNext {
				i += 2
			} else {
				i++
			}
			continue
		} else {
			// positional
			posArgs = append(posArgs, arg)
			i++
			continue
		}
	}

	// After loop, set cfg fields from seen
	cfg.showHelp = seenHelp
	cfg.showVersion = seenVersion
	cfg.text = seenText
	cfg.pretty = seenPretty
	cfg.detectBase = seenDetectBase
	cfg.ignoreWhitespace = seenIgnoreWs
	cfg.removeNodes = removeNodes
	cfg.selectors = posArgs

	// Handle help/version precedence: if help or version present, ignore errors and return help/version
	if seenHelp {
		return cfg, 0, ""
	}
	if seenVersion {
		return cfg, 0, ""
	}
	if hasErr {
		// Need to fix USAGE for missing errors to include ALL present flags (including those after missing).
		// Our presentSet already includes all seen flags (since we added as we parsed, including after missing).
		// But for missing errors, our msg was generated with partial present (only before). Need to regenerate with full present.
		// Check if first error was missing: regenerate
		if strings.Contains(firstErrMsg, "requires a value") {
			// extract missing long from msg? Parse: "error: The argument 'X' requires..."
			// Find between "'"
			start := strings.Index(firstErrMsg, "'")
			end := strings.Index(firstErrMsg[start+1:], "'")
			if start != -1 && end != -1 {
				missingLong := firstErrMsg[start+1 : start+1+end]
				present := presentList()
				// Ensure missing is in present (it should be, we added)
				msg := usageForMissing(missingLong, present)
				firstErrMsg = msg
			}
		} else if strings.Contains(firstErrMsg, "more than once") {
			start := strings.Index(firstErrMsg, "'")
			end := strings.Index(firstErrMsg[start+1:], "'")
			if start != -1 && end != -1 {
				dupLong := firstErrMsg[start+1 : start+1+end]
				present := presentList()
				msg := usageForDuplicate(dupLong, present)
				firstErrMsg = msg
			}
		}
		return nil, firstErrCode, firstErrMsg
	}
	return cfg, 0, ""
}

func newString(s string) *string {
	v := s
	return &v
}

func isFlagLike(s string) bool {
	if s == "--" {
		return true
	}
	if strings.HasPrefix(s, "--") && len(s) > 2 {
		// Could be --unknown or --help etc. All long starting with -- are flag-like, even if unknown? For value detection, clap treats next arg starting with - as flag-like only if it's known? Test: -a -x where -x unknown: is "-x" considered value or missing?
