		// For now, treat any starting with - as flag-like, except single "-"?
		return true
	}
	if strings.HasPrefix(s, "-") && len(s) > 1 {
		// short flag-like? Could be "-p" etc. or negative number? For attribute values, "-p" could be value? But clap treats "-p" as flag, not value, as we saw -a -t is missing, not value.
		// What about -a -123? Is "-123" value or flag? Unknown. For simplicity, treat any -X as flag-like.
		// But what about selector "-p" after --? That's positional, not here.
		// What about value that legitimately starts with - like "-foo" as attribute? Unlikely in tests. We'll treat as flag-like.
		return true
	}
	return false
}
