func handleFileError(err error, isInput bool) int {
	if isInput {
		if os.IsNotExist(err) {
			pid := os.Getpid()
			fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at src/main.rs:196:37:\nshould have opened input file: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid)
			return 101
		}
		if isDirError(err) {
			fmt.Fprintf(os.Stderr, "Error: Os { code: 21, kind: IsADirectory, message: \"Is a directory\" }\n")
			return 1
		}
		// fallback: check error string contains "is a directory"
		if strings.Contains(err.Error(), "is a directory") {
			fmt.Fprintf(os.Stderr, "Error: Os { code: 21, kind: IsADirectory, message: \"Is a directory\" }\n")
			return 1
		}
		pid := os.Getpid()
		fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at src/main.rs:196:37:\nshould have opened input file: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid)
		return 101
	} else {
		if os.IsNotExist(err) {
			pid := os.Getpid()
			fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at src/main.rs:202:39:\nshould have created output file: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid)
			return 101
		}
		if isDirError(err) || strings.Contains(err.Error(), "is a directory") {
			pid := os.Getpid()
			fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at src/main.rs:202:39:\nshould have created output file: Os { code: 21, kind: IsADirectory, message: \"Is a directory\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid)
			return 101
		}
		pid := os.Getpid()
		fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at src/main.rs:202:39:\nshould have created output file: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid)
		return 101
	}
}

func isDirError(err error) bool {
	s := err.Error()
	return strings.Contains(s, "is a directory")
}

func readInputFile(path string) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return nil, err
	}
	if fi.IsDir() {
		return nil, &os.PathError{Op: "open", Path: path, Err: fmt.Errorf("is a directory")}
	}
	data, err := io.ReadAll(f)
	if err != nil {
		if strings.Contains(err.Error(), "is a directory") {
			return nil, &os.PathError{Op: "read", Path: path, Err: fmt.Errorf("is a directory")}
		}
		return nil, err
	}
	return data, nil
}
