func parseSelectorList(s string) ([]ComplexSelector, error) {
	// split by commas at top level (not inside brackets/parens/quotes)
	parts, err := splitByCommas(s)
	if err != nil {
		return nil, err
	}
	if len(parts) == 0 {
		return nil, fmt.Errorf("empty")
	}
	var result []ComplexSelector
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			return nil, fmt.Errorf("empty part")
		}
		c, err := parseComplex(p)
		if err != nil {
			return nil, err
		}
		result = append(result, c)
	}
	if len(result) == 0 {
		return nil, fmt.Errorf("empty")
	}
	return result, nil
}

func splitByCommas(s string) ([]string, error) {
	var parts []string
	depthBracket := 0
	depthParen := 0
	inSingle := false
	inDouble := false
	escape := false
	start := 0
	for i, r := range s {
		if escape {
			escape = false
			continue
		}
		if r == '\\' && (inSingle || inDouble) {
			escape = true
			continue
		}
		if r == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if r == '"' && !inSingle {
			inDouble = !inDouble
			continue
		}
		if inSingle || inDouble {
			continue
		}
		if r == '[' {
			depthBracket++
		} else if r == ']' {
			depthBracket--
			if depthBracket < 0 {
				return nil, fmt.Errorf("unmatched ]")
			}
		} else if r == '(' {
			depthParen++
		} else if r == ')' {
			depthParen--
			if depthParen < 0 {
				return nil, fmt.Errorf("unmatched )")
			}
		} else if r == ',' && depthBracket == 0 && depthParen == 0 {
			parts = append(parts, s[start:i])
			start = i + 1
		}
		_ = i
	}
	if inSingle || inDouble {
		return nil, fmt.Errorf("unclosed quote")
	}
	if depthBracket != 0 || depthParen != 0 {
		return nil, fmt.Errorf("unclosed")
	}
	parts = append(parts, s[start:])
	return parts, nil
}

func parseComplex(s string) (ComplexSelector, error) {
	// Tokenize into compounds and combinators
	// Need to handle combinators: ' ', '>', '+', '~' with optional whitespace
	// Split by combinators at top level (not inside brackets/parens/quotes)
	var compounds []CompoundSelector
	var combinators []Combinator
	i := 0
	n := len(s)
	skipSpaces := func() {
		for i < n && isSpace(s[i]) {
