		return ComplexSelector{}, fmt.Errorf("empty complex")
	}
	// parse first compound
	comp, err := parseCompound(s, &i)
	if err != nil {
		return ComplexSelector{}, err
	}
	compounds = append(compounds, comp)
	for {
		// after compound, skip spaces and check for combinator or end
		startSpace := i
		for i < n && isSpace(s[i]) {
			i++
		}
		hasSpace := i > startSpace
		if i >= n {
			break
		}
		c := s[i]
		var comb Combinator
		var hasComb bool
		if c == '>' {
			comb = Child
			hasComb = true
			i++
		} else if c == '+' {
			comb = AdjacentSibling
			hasComb = true
			i++
		} else if c == '~' {
			comb = GeneralSibling
			hasComb = true
			i++
		} else if hasSpace {
			comb = Descendant
			hasComb = true
			// don't consume, just descendant (spaces already consumed)
		} else {
			// No space, no combinator char, but next is start of compound without separator? That's invalid (e.g., "divp"? Actually "divp" is single compound, not two. Our parseCompound would have consumed full compound, so this shouldn't happen unless there's invalid char.
