			return ComplexSelector{}, fmt.Errorf("unexpected char %q", c)
		}
		if hasComb {
			// skip spaces after combinator
			for i < n && isSpace(s[i]) {
				i++
			}
			if i >= n {
				return ComplexSelector{}, fmt.Errorf("trailing combinator")
			}
			// check for extra combinator chars (e.g., "div >> p" invalid)
			if s[i] == '>' || s[i] == '+' || s[i] == '~' {
				return ComplexSelector{}, fmt.Errorf("double combinator")
			}
			comp2, err := parseCompound(s, &i)
			if err != nil {
				return ComplexSelector{}, err
			}
			compounds = append(compounds, comp2)
			combinators = append(combinators, comb)
		}
	}
	return ComplexSelector{compounds: compounds, combinators: combinators}, nil
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f'
}

func isNameStart(r rune) bool {
	return r == '_' || r == '-' || unicode.IsLetter(r) || r >= 0x80
}
func isNameChar(r rune) bool {
	return isNameStart(r) || unicode.IsDigit(r)
