					if next < n && s[next] == '|' {
						ns = &ident
						hasPipe = true
						i = next + 1
					}
					// else, not ns, leave i as saved (will parse as name below)
				}
			}
		}
		_ = saved
	}
	// Now parse name (must be ident)
	// Skip spaces? Actually after ns| there may be spaces? e.g., [*| href]? Probably allow spaces. Skip.
	for i < n && isSpace(s[i]) {
		i++
	}
	nameStr, next, err := parseIdent(s, i)
	if err != nil {
		return AttrSelector{}, start, fmt.Errorf("invalid attr name")
	}
	i = next
	// Validate namespace for attr: only "*" or "" allowed, others error (like html|href)
	if hasPipe {
		nsVal := ""
		if ns != nil {
			nsVal = *ns
		}
		if nsVal != "*" && nsVal != "" {
			return AttrSelector{}, start, fmt.Errorf("unknown attr namespace")
		}
	}
	// skip spaces
	for i < n && isSpace(s[i]) {
		i++
	}
	if i >= n {
		return AttrSelector{}, start, fmt.Errorf("unclosed [")
	}
	if s[i] == ']' {
		// existence
		i++
		return AttrSelector{name: strings.ToLower(nameStr), op: ""}, i, nil
	}
	// operator
	var op string
	if i+1 < n && s[i+1] == '=' {
		if s[i] == '=' || s[i] == '~' || s[i] == '|' || s[i] == '^' || s[i] == '$' || s[i] == '*' {
			op = string([]byte{s[i], '='})
			i += 2
		} else if s[i] == '!' {
			// != invalid
			return AttrSelector{}, start, fmt.Errorf("invalid op !=")
		} else {
			return AttrSelector{}, start, fmt.Errorf("invalid op")
		}
	} else if s[i] == '=' {
		op = "="
		i++
	} else {
		return AttrSelector{}, start, fmt.Errorf("expected op or ]")
	}
	// skip spaces
	for i < n && isSpace(s[i]) {
		i++
	}
	if i >= n {
		return AttrSelector{}, start, fmt.Errorf("expected value")
	}
	// parse value: string ("..." or '...') or ident
	var valStr string
	if s[i] == '"' || s[i] == '\'' {
		quote := s[i]
		i++
		var buf strings.Builder
		for i < n {
			if s[i] == '\\' {
				// escape
				esc, next, err := parseEscape(s, i)
				if err != nil {
					return AttrSelector{}, start, err
				}
				buf.WriteString(esc)
				i = next
			} else if s[i] == quote {
				i++
				break
			} else if s[i] == '\n' || s[i] == '\r' || s[i] == '\f' {
				return AttrSelector{}, start, fmt.Errorf("newline in string")
			} else {
				r, size := utf8.DecodeRuneInString(s[i:])
				buf.WriteRune(r)
				i += size
			}
		}
		valStr = buf.String()
	} else {
		// ident value
		v, next, err := parseIdent(s, i)
		if err != nil {
			return AttrSelector{}, start, err
		}
		valStr = v
		i = next
	}
	// skip spaces
	for i < n && isSpace(s[i]) {
		i++
	}
	// optional case flag: i or s (single letter ident)
	ignoreCase := false
	// Check for flag: if next is ident of length 1 (i/s) then spaces then ]?
	// Actually syntax: [attr=value i] where i is separate ident
	savedFlag := i
	if i < n && (s[i] == 'i' || s[i] == 'I' || s[i] == 's' || s[i] == 'S') {
		// Need to ensure it's standalone (followed by spaces and ])
		j := i + 1
		// Check that previous char was space? Actually flag must be separated by whitespace from value? e.g., [href=x i] valid, [href=xi] not flag. Since we skipped spaces after value, i is at flag start if flag present (must have been separated by at least one space? Our skip already consumed spaces, but we need to ensure there was at least one space between value and flag? For [href=x i], value "x" then space then "i". Our i after skipping spaces is at "i". Good. For [href=xi], value would be "xi" (parsed as ident "xi"), not "x" + flag. So no issue.
		// Peek to see if after flag there are spaces and ]
		k := j
		for k < n && isSpace(s[k]) {
			k++
		}
		if k < n && s[k] == ']' {
			// It's flag
			if s[i] == 'i' || s[i] == 'I' {
				ignoreCase = true
			} else {
				ignoreCase = false
			}
			i = j
			for i < n && isSpace(s[i]) {
				i++
			}
		} else {
			// Not flag, must be error (expected ])? Actually [href=x y] invalid -> error
			// If next is not ] and not flag, error
			if k >= n || s[k] != ']' {
				// Check if j is at ]? No, need to error
				// For [href=x y], after value "x", i at "y", not flag? Actually "y" is not i/s, so we go here. Should error.
				return AttrSelector{}, start, fmt.Errorf("expected ]")
			}
		}
		_ = savedFlag
	}
	if i >= n || s[i] != ']' {
		return AttrSelector{}, start, fmt.Errorf("expected ]")
	}
	i++
	return AttrSelector{name: strings.ToLower(nameStr), op: op, value: valStr, ignoreCase: ignoreCase}, i, nil
}

func parsePseudo(s string, start int) (PseudoSelector, int, error) {
	// s[start] == ':'
	n := len(s)
	i := start + 1
	// parse ident
	name, next, err := parseIdent(s, i)
	if err != nil {
		return PseudoSelector{}, start, err
	}
	i = next
	lower := strings.ToLower(name)
	// Check if it takes args: nth-* and not and lang/dir etc. (but lang/dir are invalid -> error)
	// For valid no-arg pseudos, must NOT have parens? e.g., :first-child() invalid? Probably error. Check: :first-child with () should be error? Let's treat as error if parens present for no-arg.
	if _, ok := validNoArgPseudos[lower]; ok {
		// Check for '(' -> error (since no-arg pseudos shouldn't have args)
		// Skip? Actually :hover() invalid? Probably error. Return error if '(' follows (after optional spaces? No spaces allowed between pseudo and paren? e.g., :not (p) invalid? Probably error. For simplicity, if next char is '(', error for no-arg pseudos except? Let's check :not and nth-* need parens.
		if i < n && s[i] == '(' {
			// For no-arg, having parens is invalid
			return PseudoSelector{}, start, fmt.Errorf("unexpected ( for %s", lower)
		}
		return PseudoSelector{name: lower}, i, nil
	}
	if _, ok := nthPseudos[lower]; ok {
		// must have (arg)
		if i >= n || s[i] != '(' {
			return PseudoSelector{}, start, fmt.Errorf("expected ( for %s", lower)
		}
		// find matching )
		j := i + 1
		depth := 1
		for j < n && depth > 0 {
			if s[j] == '(' {
				depth++
			} else if s[j] == ')' {
				depth--
			}
			j++
		}
		if depth != 0 {
			return PseudoSelector{}, start, fmt.Errorf("unclosed (")
		}
		arg := s[i+1 : j-1]
		a, b, err := parseNth(arg)
		if err != nil {
			return PseudoSelector{}, start, err
		}
		return PseudoSelector{name: lower, arg: arg, nthA: a, nthB: b}, j, nil
	}
	if lower == "not" {
		if i >= n || s[i] != '(' {
			return PseudoSelector{}, start, fmt.Errorf("expected ( for not")
		}
		j := i + 1
		depth := 1
		for j < n && depth > 0 {
			if s[j] == '(' {
				depth++
			} else if s[j] == ')' {
				depth--
			}
			j++
		}
		if depth != 0 {
			return PseudoSelector{}, start, fmt.Errorf("unclosed (")
		}
		innerStr := strings.TrimSpace(s[i+1 : j-1])
		if innerStr == "" {
			return PseudoSelector{}, start, fmt.Errorf("empty not")
		}
		// Inner must be single simple selector (no combinators, no commas, single compound with single simple?)
		// Parse as compound and validate it contains exactly one simple selector
		innerPos := 0
		innerComp, err := parseCompound(innerStr, &innerPos)
		if err != nil {
			return PseudoSelector{}, start, err
		}
		if innerPos != len(innerStr) {
			// Extra chars (combinators etc.) -> invalid
			return PseudoSelector{}, start, fmt.Errorf("complex not")
		}
		// Count simple selectors in compound
		count := 0
		var single SimpleSelector
		if innerComp.tag != nil {
			// Tag counts as one, but if tag is "*" universal? That's still one? :not(*) valid (we saw). So count it.
			count++
			single.kind = "tag"
			single.tag = innerComp.tag
		}
		if innerComp.id != nil {
			count++
			if count == 1 {
				single.kind = "id"
				single.id = innerComp.id
			}
		}
		for _, c := range innerComp.classes {
			count++
			if count == 1 {
				single.kind = "class"
				v := c
				single.class = &v
			}
		}
		for _, a := range innerComp.attrs {
			count++
			if count == 1 {
				single.kind = "attr"
				v := a
				single.attr = &v
			}
		}
		for _, p := range innerComp.pseudos {
			count++
			if count == 1 {
				single.kind = "pseudo"
				v := p
				single.pseudo = &v
			}
		}
		if count != 1 {
			return PseudoSelector{}, start, fmt.Errorf("not must have single simple")
		}
		// Also, inner pseudo cannot be :not (nested not invalid)
		if single.kind == "pseudo" && single.pseudo.name == "not" {
			return PseudoSelector{}, start, fmt.Errorf("nested not")
		}
		return PseudoSelector{name: "not", arg: innerStr, notInner: &single}, j, nil
	}
	// Unknown pseudo -> error (panic)
	return PseudoSelector{}, start, fmt.Errorf("unknown pseudo %s", lower)
}

func parseNth(s string) (int, int, error) {
	t := strings.TrimSpace(strings.ToLower(s))
	if t == "odd" {
		return 2, 1, nil
	}
	if t == "even" {
		return 2, 0, nil
	}
	// Try single integer?
	if v, err := strconv.Atoi(strings.TrimSpace(t)); err == nil {
		return 0, v, nil
	}
	// An+B form: e.g., "2n", "2n+1", "-n+3", "n", "-n", "+n", "n+1", etc.
	// Remove spaces
	nospace := strings.ReplaceAll(strings.ReplaceAll(t, " ", ""), "\t", "")
	// Find 'n'
	idx := strings.Index(nospace, "n")
	if idx == -1 {
		return 0, 0, fmt.Errorf("invalid nth %q", s)
	}
	aStr := nospace[:idx]
	bStr := nospace[idx+1:]
	var a int
	if aStr == "" || aStr == "+" {
		a = 1
	} else if aStr == "-" {
		a = -1
	} else {
		v, err := strconv.Atoi(aStr)
		if err != nil {
			return 0, 0, fmt.Errorf("invalid nth a")
		}
		a = v
	}
	var b int
	if bStr == "" {
		b = 0
	} else {
		// bStr should be like "+1", "-2", "+1", etc. Must start with + or - ?
		if bStr[0] != '+' && bStr[0] != '-' {
			return 0, 0, fmt.Errorf("invalid nth b")
		}
		v, err := strconv.Atoi(bStr)
		if err != nil {
			return 0, 0, fmt.Errorf("invalid nth b")
		}
		b = v
	}
	return a, b, nil
}

// Matching

func collectElements(doc *html.Node) []*html.Node {
	var out []*html.Node
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			out = append(out, n)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)
	return out
}

func matchComplex(el *html.Node, sel ComplexSelector, doc *html.Node) bool {
	// Match from rightmost compound
	idx := len(sel.compounds) - 1
	if !matchCompound(el, sel.compounds[idx]) {
		return false
	}
	cur := el
	for idx > 0 {
		comb := sel.combinators[idx-1]
		left := sel.compounds[idx-1]
		switch comb {
		case Descendant:
			// find ancestor matching left
			p := cur.Parent
			found := false
			for p != nil {
				if p.Type == html.ElementNode && matchCompound(p, left) {
					found = true
					cur = p
					break
				}
				p = p.Parent
			}
			if !found {
				return false
			}
		case Child:
			p := cur.Parent
			if p == nil || p.Type != html.ElementNode || !matchCompound(p, left) {
				return false
			}
			cur = p
		case AdjacentSibling:
			sib := prevElementSibling(cur)
			if sib == nil || !matchCompound(sib, left) {
				return false
			}
			cur = sib
		case GeneralSibling:
			sib := cur.PrevSibling
			found := false
			for sib != nil {
				if sib.Type == html.ElementNode && matchCompound(sib, left) {
					found = true
					cur = sib
					break
				}
				sib = sib.PrevSibling
			}
			if !found {
				return false
			}
		}
		idx--
	}
	return true
}

func matchCompound(el *html.Node, comp CompoundSelector) bool {
	// tag
	if comp.tag != nil {
		if !matchTag(el, comp.tag) {
			return false
		}
	}
	// id
	if comp.id != nil {
		if getAttr(el, "id") != *comp.id {
			return false
		}
	}
	// classes
	if len(comp.classes) > 0 {
		classAttr := getAttr(el, "class")
		// class matching: case-sensitive? Original: .X doesn't match class="x" (case-sensitive). So case-sensitive.
		// Split by whitespace
		classes := strings.Fields(classAttr)
		set := map[string]bool{}
		for _, c := range classes {
			set[c] = true
		}
		for _, need := range comp.classes {
			if !set[need] {
				return false
			}
		}
	}
	// attrs
	for _, a := range comp.attrs {
		if !matchAttr(el, a) {
			return false
		}
	}
	// pseudos
	for _, p := range comp.pseudos {
		if !matchPseudo(el, p) {
			return false
		}
	}
	return true
}

func matchTag(el *html.Node, tag *TagSelector) bool {
	if tag.name == "*" {
		if tag.hasPipe {
			ns := tag.namespace
			if ns == "*" {
				return true // *|* matches all
			} else if ns == "" {
				return false // |* matches none (no namespace)
			}
		}
		return true
	}
	// normal tag
	elTag := strings.ToLower(el.Data)
	if elTag != tag.name {
		return false
	}
	if tag.hasPipe {
		ns := tag.namespace
		if ns == "*" {
			return true // *|div matches
		} else if ns == "" {
			return false // |div matches none (since HTML elements have namespace)
		}
	}
	return true
}

func getAttr(el *html.Node, name string) string {
	lower := strings.ToLower(name)
	for _, a := range el.Attr {
		if strings.ToLower(a.Key) == lower {
			return a.Val
		}
	}
	return ""
}

func hasAttr(el *html.Node, name string) (string, bool) {
	lower := strings.ToLower(name)
	for _, a := range el.Attr {
		if strings.ToLower(a.Key) == lower {
			return a.Val, true
		}
	}
	return "", false
}

func matchAttr(el *html.Node, sel AttrSelector) bool {
	val, ok := hasAttr(el, sel.name)
	if !ok {
		return false
	}
	if sel.op == "" {
		return true
	}
	// For value matching, need case handling
	compareVal := val
	target := sel.value
	if sel.ignoreCase {
		compareVal = strings.ToLower(compareVal)
		target = strings.ToLower(target)
	}
	switch sel.op {
	case "=":
		return compareVal == target
	case "~=":
		// whitespace-separated list contains
		parts := strings.Fields(compareVal)
		// For ignoreCase, parts already lower? Actually compareVal lower, target lower, so ok. For case-sensitive, exact.
		for _, p := range parts {
			if p == target {
				return true
			}
		}
		return false
	case "|=":
		// exactly or followed by -
		if compareVal == target {
			return true
		}
		if strings.HasPrefix(compareVal, target+"-") {
			return true
		}
		return false
	case "^=":
		if target == "" {
			return false // [attr^=""] never matches? In CSS, empty string with ^= etc. never matches. Need to handle: if value is empty, return false for ^=, $=, *= ?
		}
		return strings.HasPrefix(compareVal, target)
	case "$=":
		if target == "" {
			return false
		}
		return strings.HasSuffix(compareVal, target)
	case "*=":
		if target == "" {
			return false
		}
		return strings.Contains(compareVal, target)
	}
	return false
}

func matchPseudo(el *html.Node, p PseudoSelector) bool {
	switch p.name {
	case "first-child":
		return isFirstChild(el)
	case "last-child":
		return isLastChild(el)
	case "only-child":
		return isFirstChild(el) && isLastChild(el)
	case "first-of-type":
		return isFirstOfType(el)
	case "last-of-type":
		return isLastOfType(el)
	case "only-of-type":
		return isFirstOfType(el) && isLastOfType(el)
	case "nth-child":
		return matchNth(childIndex(el), p.nthA, p.nthB)
	case "nth-last-child":
		return matchNth(childIndexFromEnd(el), p.nthA, p.nthB)
	case "nth-of-type":
		return matchNth(ofTypeIndex(el), p.nthA, p.nthB)
	case "nth-last-of-type":
		return matchNth(ofTypeIndexFromEnd(el), p.nthA, p.nthB)
	case "not":
		if p.notInner == nil {
			return false
		}
		return !matchSimple(el, p.notInner)
	case "empty":
		return isEmpty(el)
	case "root":
		// html element?
		return strings.ToLower(el.Data) == "html"
	case "scope":
		// In kuchiki, :scope matches root? For our test, :scope matched html. So same as root?
		return strings.ToLower(el.Data) == "html"
	case "hover", "active", "focus", "link", "visited", "any-link", "checked", "indeterminate", "enabled", "disabled":
		// These never match in static context? Check: :link etc. never matched in our tests. :enabled/:disabled also never? For <input disabled>, does :disabled match? Let's test: does :disabled match disabled input? Our earlier test with :disabled gave empty for <div><p>..., but need to test with disabled input.
		// For now, return false for all, but need to handle :enabled/:disabled/:checked specially? Let's check original behavior for those with appropriate elements.
		// To be safe, implement :enabled/:disabled/:checked matching for form elements? Or just return false? Need to test.
		return false
	}
	return false
}

func matchSimple(el *html.Node, s *SimpleSelector) bool {
	switch s.kind {
	case "tag":
		return matchTag(el, s.tag)
	case "id":
		return getAttr(el, "id") == *s.id
	case "class":
		classAttr := getAttr(el, "class")
		parts := strings.Fields(classAttr)
		for _, p := range parts {
			if p == *s.class {
				return true
			}
		}
		return false
	case "attr":
		return matchAttr(el, *s.attr)
	case "pseudo":
		return matchPseudo(el, *s.pseudo)
	}
	return false
}

// Helpers for pseudo
func prevElementSibling(n *html.Node) *html.Node {
	p := n.PrevSibling
	for p != nil && p.Type != html.ElementNode {
		p = p.PrevSibling
	}
	return p
}
func nextElementSibling(n *html.Node) *html.Node {
	p := n.NextSibling
	for p != nil && p.Type != html.ElementNode {
		p = p.NextSibling
	}
	return p
}
func isFirstChild(el *html.Node) bool {
	// :first-child counts element siblings only (ignores text/comments)? Test earlier: <div>text<p>hi</p></div> with p:first-child matched (even though text before). So text ignored. Good.
	return prevElementSibling(el) == nil
}
func isLastChild(el *html.Node) bool {
	return nextElementSibling(el) == nil
}
func isFirstOfType(el *html.Node) bool {
	tag := strings.ToLower(el.Data)
	p := el.PrevSibling
	for p != nil {
		if p.Type == html.ElementNode && strings.ToLower(p.Data) == tag {
			return false
		}
		p = p.PrevSibling
	}
	return true
}
func isLastOfType(el *html.Node) bool {
	tag := strings.ToLower(el.Data)
	p := el.NextSibling
	for p != nil {
		if p.Type == html.ElementNode && strings.ToLower(p.Data) == tag {
			return false
		}
		p = p.NextSibling
	}
	return true
}
func childIndex(el *html.Node) int {
	// 1-based index among element siblings
	idx := 1
	p := el.PrevSibling
	for p != nil {
		if p.Type == html.ElementNode {
			idx++
		}
		p = p.PrevSibling
	}
	return idx
}
func childIndexFromEnd(el *html.Node) int {
	idx := 1
	p := el.NextSibling
	for p != nil {
		if p.Type == html.ElementNode {
