		p = p.NextSibling
	}
	return idx
}
func matchNth(idx, a, b int) bool {
	if a == 0 {
		return idx == b
	}
	// Check if idx matches a*n + b for some n >= 0
	// For negative a, n still >=0, but idx must be >=1
	diff := idx - b
	if a > 0 {
		if diff < 0 {
			return false
		}
		return diff%a == 0
	} else {
		if diff > 0 {
			return false
		}
		return diff%a == 0
	}
}
